  /// best-effort teardown; nothing needs the completion guarantees.
  Future<void> disconnect() async {
    _manualClose = true;
    _reconnectTimer?.cancel();
    _reconnectTimer = null;
    _heartbeatTimer?.cancel();
    _heartbeatTimer = null;
    _connected = false;
    final subscription = _subscription;
    _subscription = null;
    if (subscription != null) unawaited(subscription.cancel());
    final channel = _channel;
    _channel = null;
    if (channel != null) unawaited(channel.sink.close());
  }

  /// [disconnect] plus closes the [events] stream.
  Future<void> dispose() async {
    await disconnect();
    unawaited(_events.close());
  }

  // ------------------------------------------------------------------ open

  Future<void> _open() async {
    if (_connected || _connecting || _manualClose || _events.isClosed) return;
    _connecting = true;
    final StreamChannel<String> channel;
    try {
      channel = await connector.connect(wsUri, {
        'Authorization': 'Bearer ${sessionToken()}',
      });
    } catch (_) {
      _connecting = false;
      _scheduleReconnect();
      return;
    }
    _connecting = false;
    if (_manualClose || _events.isClosed) {
      unawaited(channel.sink.close());
      return;
    }
    _channel = channel;
    _connected = true;
    _attempts = 0;
    _subscription = channel.stream.listen(
      _onFrame,
      onError: _onChannelError,
      onDone: _onChannelClosed,
    );
